export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const tTop = u / g;
  const yTop = (u * u) / (2 * g);

  const t = Math.min(time, 2 * tTop);

  // Tossed ball kinematics
  const vToss = u - g * t;
  const yToss = u * t - 0.5 * g * t * t;
  const aToss = -g;

  // Dropped ball kinematics
  let vDrop = 0;
  let yDrop = yTop;
  let aDrop = 0;
  if (t >= tTop) {
    const dt = t - tTop;
    vDrop = -g * dt;
    yDrop = yTop - 0.5 * g * dt * dt;
    aDrop = -g;
  }

  // Lane coordinate transformations: y in [0, 2.2] m -> canvas Y
  // Frame size: 640 x 420
  // Lane bounds: Y from 40 to 390 (height 350). Ground y=0 is at Y=370, y=2.2 is at Y=70 (300 px = 2.2 m => 136.36 px/m)
  const pxPerM = 136.36;
  const groundY = 370;
  function toCanvasY(yM) {
    return groundY - yM * pxPerM;
  }

  const tossX = 160;
  const dropX = 480;

  const yTossPx = toCanvasY(yToss);
  const yDropPx = toCanvasY(yDrop);
  const yTopPx = toCanvasY(yTop);

  // State labels
  let stateToss = "At launch";
  if (t >= 2 * tTop - 0.001) {
    stateToss = "At launch height";
  } else if (Math.abs(t - tTop) < 0.005) {
    stateToss = "At the top";
  } else if (t < tTop) {
    stateToss = "Rising";
  } else {
    stateToss = "Falling";
  }

  let stateDrop = "Held in place";
  if (t >= 2 * tTop - 0.001) {
    stateDrop = "At launch height";
  } else if (Math.abs(t - tTop) < 0.005) {
    stateDrop = "Just released";
  } else if (t > tTop) {
    stateDrop = "Falling together";
  }

  const frameObjects = [];

  // Panels
  frameObjects.push(...sdk.panel({ x: 10, y: 35, w: 300, h: 365, title: "Toss Lane", state: stateToss, id: "lane.toss" }));
  frameObjects.push(...sdk.panel({ x: 330, y: 35, w: 300, h: 365, title: "Drop Lane", state: stateDrop, id: "lane.drop" }));

  // Ground marks
  frameObjects.push(...sdk.groundMark("ground.toss", tossX, groundY, 180, "0.0 m (Launch)"));
  frameObjects.push(...sdk.groundMark("ground.drop", dropX, groundY, 180, "0.0 m (Launch)"));

  // Gate in Drop lane at apex height
  const gateOpen = t >= tTop;
  frameObjects.push(...sdk.gate("gate", dropX, yTopPx, { open: gateOpen, w: 48, label: gateOpen ? "Open" : "Held" }));

  // Ghost outlines at starting apex height after release
  if (t > tTop) {
    frameObjects.push(
      sdk.circle("ghost.toss", tossX, yTopPx, 28, { role: "neutral", opacity: 0.35 }),
      sdk.circle("ghost.drop", dropX, yTopPx, 28, { role: "neutral", opacity: 0.35 })
    );
  }

  // Balls
  frameObjects.push(sdk.circle("ball.toss", tossX, yTossPx, 28, { role: "learner" }));
  frameObjects.push(sdk.circle("ball.drop", dropX, yDropPx, 28, { role: "observed" }));

  // Vectors
  // Velocity scale: 1 m/s = 25 px
  const vScale = 25;
  // Acceleration scale: 1 m/s^2 = 8 px
  const aScale = 8;

  frameObjects.push(
    ...sdk.vector("vec.v.toss", { x: tossX - 22, y: yTossPx }, { value: vToss, direction: "up" }, { scale: vScale, label: "v" }),
    ...sdk.vector("vec.a.toss", { x: tossX + 22, y: yTossPx }, { value: aToss, direction: "up" }, { scale: aScale, label: "a" }),
    ...sdk.vector("vec.v.drop", { x: dropX - 22, y: yDropPx }, { value: vDrop, direction: "up" }, { scale: vScale, label: "v" }),
    ...sdk.vector("vec.a.drop", { x: dropX + 22, y: yDropPx }, { value: aDrop, direction: "up" }, { scale: aScale, label: "a" })
  );

  // Callouts
  const calloutTossLines = [
    `v: ${sdk.format(vToss, 2)} m/s`,
    `a: ${sdk.format(aToss, 2)} m/s²`
  ];
  const calloutDropLines = [
    `v: ${sdk.format(vDrop, 2)} m/s`,
    `a: ${sdk.format(aDrop, 2)} m/s²`
  ];

  frameObjects.push(
    ...sdk.callout(tossX + 50, yTossPx - 20, calloutTossLines, { id: "callout.toss", role: "learner" }),
    ...sdk.callout(dropX + 50, yDropPx - 20, calloutDropLines, { id: "callout.drop", role: "observed" })
  );

  return {
    frame: {
      width: 640,
      height: 420,
      objects: frameObjects,
      readouts: [
        { id: "tossedVelocity", value: vToss },
        { id: "tossedAcceleration", value: aToss },
        { id: "dropVelocity", value: vDrop },
        { id: "dropAcceleration", value: aDrop }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      apexTime: tTop,
      apexHeight: yTop,
      tossedVelocity: vToss,
      tossedAcceleration: aToss,
      tossedHeight: yToss,
      dropVelocity: vDrop,
      dropAcceleration: aDrop,
      dropHeight: yDrop
    }
  };
}
